"use client";

/**
 * auto-solve-context.tsx
 *
 * Provides the auto-solve toggle state across the entire app without a
 * full Zustand dependency.  State is stored in sessionStorage so it
 * persists across in-session navigations but resets on tab close.
 *
 * Also maintains the live queue status by connecting to the SSE feed.
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";

import { api } from "./api";
import type { QueueStatus } from "./types";

const DEFAULT_STATUS: QueueStatus = {
  isRunning: false,
  currentTicketId: null,
  currentTicketNum: null,
  remainingCount: 0,
  processedCount: 0,
  failedCount: 0,
};

interface AutoSolveCtx {
  autoSolve: boolean;
  queueStatus: QueueStatus;
  isToggling: boolean;
  enable: () => Promise<void>;
  disable: () => Promise<void>;
}

const Ctx = createContext<AutoSolveCtx>({
  autoSolve: false,
  queueStatus: DEFAULT_STATUS,
  isToggling: false,
  enable: async () => {},
  disable: async () => {},
});

const SESSION_KEY = "buena:autoSolve";

export function AutoSolveProvider({ children }: { children: React.ReactNode }) {
  const [autoSolve, setAutoSolve] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return sessionStorage.getItem(SESSION_KEY) === "true";
  });
  const [queueStatus, setQueueStatus] = useState<QueueStatus>(DEFAULT_STATUS);
  const [isToggling, setIsToggling] = useState(false);
  const abortRef = useRef<AbortController | null>(null);

  // Keep sessionStorage in sync
  useEffect(() => {
    if (typeof window !== "undefined") {
      sessionStorage.setItem(SESSION_KEY, String(autoSolve));
    }
  }, [autoSolve]);

  // Connect to the SSE feed to receive live status updates
  useEffect(() => {
    let cancelled = false;
    const ctrl = new AbortController();
    abortRef.current = ctrl;

    const connect = async () => {
      try {
        await api.agentQueue.streamFeed({
          signal: ctrl.signal,
          onQueueStatus: (s) => {
            if (!cancelled) {
              setQueueStatus(s);
              if (!s.isRunning && autoSolve) {
                // Queue stopped (e.g. queue exhausted)
                setAutoSolve(false);
              }
            }
          },
          onQueueStopped: () => {
            if (!cancelled) setAutoSolve(false);
          },
        });
      } catch {
        // Reconnect after 3s if not cancelled
        if (!cancelled) {
          setTimeout(() => {
            if (!cancelled) connect();
          }, 3000);
        }
      }
    };

    connect();

    // Also poll status on mount in case SSE is slow to connect
    api.agentQueue.status().then((s) => {
      if (!cancelled) {
        setQueueStatus(s);
        setAutoSolve(s.isRunning);
        sessionStorage.setItem(SESSION_KEY, String(s.isRunning));
      }
    }).catch(() => {});

    return () => {
      cancelled = true;
      ctrl.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const enable = useCallback(async () => {
    setIsToggling(true);
    try {
      const result = await api.agentQueue.start();
      setQueueStatus(result);
      setAutoSolve(true);
    } finally {
      setIsToggling(false);
    }
  }, []);

  const disable = useCallback(async () => {
    setIsToggling(true);
    try {
      const result = await api.agentQueue.stop();
      setQueueStatus(result);
      setAutoSolve(false);
    } finally {
      setIsToggling(false);
    }
  }, []);

  return (
    <Ctx.Provider value={{ autoSolve, queueStatus, isToggling, enable, disable }}>
      {children}
    </Ctx.Provider>
  );
}

export function useAutoSolve() {
  return useContext(Ctx);
}
"use client";

/**
 * activity-feed.tsx
 *
 * Collapsible panel showing a live stream of everything the auto-solve agent
 * is doing across all tickets.  Connects to the SSE feed on mount and keeps
 * the 50 most-recent entries in memory.
 *
 * Designed to sit at the bottom of the page as a persistent overlay that the
 * demo presenter can leave visible while navigating between pages.
 */

import { useEffect, useRef, useState, useCallback } from "react";
import Link from "next/link";
import { cn } from "@repo/ui/lib/utils";
import {
  ChevronDown,
  ChevronUp,
  Activity,
  CheckCircle2,
  AlertTriangle,
  Info,
  XCircle,
  Mail,
  MessageCircle,
  FileText,
  ShieldAlert,
  TicketCheck,
  Loader2,
  Zap,
} from "lucide-react";
import { api } from "@/lib/api";
import { useAutoSolve } from "@/lib/auto-solve-context";
import type { AgentActivityEntry, ActivityEventType } from "@/lib/types";

const MAX_ENTRIES = 50;

// ---------------------------------------------------------------------------
// Severity → visual config
// ---------------------------------------------------------------------------

const SEVERITY_CONFIG = {
  info:    { icon: Info,         cls: "text-blue-500",    bg: "bg-blue-500/10" },
  success: { icon: CheckCircle2, cls: "text-emerald-500", bg: "bg-emerald-500/10" },
  warning: { icon: AlertTriangle, cls: "text-amber-500",  bg: "bg-amber-500/10" },
  error:   { icon: XCircle,      cls: "text-red-500",     bg: "bg-red-500/10" },
} as const;

// ---------------------------------------------------------------------------
// Action type → icon
// ---------------------------------------------------------------------------

function ActionIcon({ actionType, eventType }: { actionType: string | null; eventType: ActivityEventType }) {
  if (eventType === "action_escalated") return <ShieldAlert className="h-3 w-3 text-amber-500" />;
  if (eventType === "action_confirmed" || eventType === "ticket_completed") return <CheckCircle2 className="h-3 w-3 text-emerald-500" />;
  if (eventType === "queue_started" || eventType === "queue_stopped") return <Zap className="h-3 w-3 text-blue-500" />;
  if (eventType === "ticket_error") return <XCircle className="h-3 w-3 text-red-500" />;
  switch (actionType) {
    case "send_vendor_email":  return <Mail className="h-3 w-3 text-muted-foreground" />;
    case "respond_to_tenant":  return <MessageCircle className="h-3 w-3 text-muted-foreground" />;
    case "send_owner_report":  return <FileText className="h-3 w-3 text-muted-foreground" />;
    case "escalate_to_human":  return <ShieldAlert className="h-3 w-3 text-amber-500" />;
    case "approve_ticket":     return <TicketCheck className="h-3 w-3 text-emerald-500" />;
    default:                   return <Activity className="h-3 w-3 text-muted-foreground" />;
  }
}

// ---------------------------------------------------------------------------
// Single feed entry row
// ---------------------------------------------------------------------------

function FeedEntry({ entry }: { entry: AgentActivityEntry }) {
  const sev = SEVERITY_CONFIG[entry.severity] ?? SEVERITY_CONFIG.info;
  const SevIcon = sev.icon;

  return (
    <div
      className={cn(
        "flex items-start gap-2 rounded-md px-3 py-2 text-xs transition-colors",
        entry.severity === "warning" && "bg-amber-500/5 border border-amber-500/20",
        entry.severity === "error" && "bg-red-500/5 border border-red-500/20",
      )}
    >
      {/* Severity icon */}
      <SevIcon className={cn("mt-0.5 h-3 w-3 shrink-0", sev.cls)} />

      {/* Content */}
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <ActionIcon actionType={entry.actionType} eventType={entry.eventType} />
          {entry.ticketNum && (
            <Link
              href={`/ticket/${entry.ticketId}`}
              className="font-mono text-[10px] font-medium text-foreground/80 hover:text-foreground hover:underline"
              onClick={(e) => e.stopPropagation()}
            >
              {entry.ticketNum}
            </Link>
          )}

