                <Item href="/buildings" icon={Building2} active={pathname.startsWith("/buildings") || pathname.startsWith("/building/")}>Buildings</Item>
              </Zone>

              <Zone label="Tools">
                <Item href="/extract" icon={FileText}          active={pathname === "/extract"}>PDF Extract</Item>
